        const __m256 t33 = _mm256_sub_ps(t32, t16);
        const __m256 t43 = _mm256_add_ps(t16, t32);
        const __m256 t39 = _mm256_add_ps(t25, t28);
        const __m256 t40 = _mm256_sub_ps(t39, t36);
        const __m256 t45 = _mm256_add_ps(t36, t39);
        const __m256 t29 = lane_im_0;
        const __m256 t30 = _mm256_sub_ps(t29, t26);
        const __m256 t34 = _mm256_add_ps(t18, t30);
        const __m256 t44 = _mm256_sub_ps(t30, t18);
