        /* ZBlockSplit load edge */
        const __m256 lane_re_0 = _mm256_loadu_ps(&zin[2*(size_t)k]);
        const __m256 lane_im_0 = _mm256_loadu_ps(&zin[2*(size_t)k + 8]);
