        const __m256 lane_im_3 = _mm256_loadu_ps(&zin[2*((size_t)3*Ls + k) + 8]);
        /* SU-scheduled body (pipeline) */
        const __m256 t0 = lane_re_3;
        const __m256 t1 = _mm256_loadu_ps(&tw_re[6*(size_t)k + 32]);
