        const __m256 t3 = _mm256_loadu_ps(&tw_re[6*(size_t)k + 40]);
        const __m256 t4 = _mm256_fnmadd_ps(t2, t3, _mm256_mul_ps(t0, t1));
        const __m256 t5 = _mm256_fmadd_ps(t0, t3, _mm256_mul_ps(t2, t1));
        const __m256 t9 = lane_re_1;
        const __m256 t10 = _mm256_loadu_ps(&tw_re[6*(size_t)k + 0]);
        const __m256 t11 = lane_im_1;
