        const __m256 t13 = _mm256_fnmadd_ps(t11, t12, _mm256_mul_ps(t9, t10));
        const __m256 t14 = _mm256_fmadd_ps(t9, t12, _mm256_mul_ps(t11, t10));
        const __m256 t16 = _mm256_sub_ps(t14, t5);
        const __m256 t18 = _mm256_sub_ps(t13, t4);
        const __m256 t35 = _mm256_add_ps(t5, t14);
        const __m256 t36 = _mm256_add_ps(t4, t13);
