        const __m256 t27 = lane_re_0;
        const __m256 t31 = _mm256_sub_ps(t27, t24);
        const __m256 t32 = _mm256_add_ps(t16, t31);
        const __m256 t43 = _mm256_sub_ps(t31, t16);
        const __m256 t39 = _mm256_add_ps(t24, t27);
        const __m256 t40 = _mm256_sub_ps(t39, t36);
        const __m256 t45 = _mm256_add_ps(t36, t39);
        const __m256 t28 = lane_im_0;
        const __m256 t29 = _mm256_sub_ps(t28, t25);
        const __m256 t34 = _mm256_sub_ps(t29, t18);
        const __m256 t44 = _mm256_add_ps(t18, t29);
