        _mm256_storeu_ps(&zout[2*((size_t)1*OLs + k) + 8], _mm256_unpackhi_ps(_pr_1, _qi_1));
        const __m256 _pr_2 = _mm256_castpd_ps(_mm256_permute4x64_pd(_mm256_castps_pd(t40), 0xD8));
        const __m256 _qi_2 = _mm256_castpd_ps(_mm256_permute4x64_pd(_mm256_castps_pd(t42), 0xD8));
        _mm256_storeu_ps(&zout[2*((size_t)2*OLs + k)], _mm256_unpacklo_ps(_pr_2, _qi_2));
        _mm256_storeu_ps(&zout[2*((size_t)2*OLs + k) + 8], _mm256_unpackhi_ps(_pr_2, _qi_2));
